/// A reference from another config to an orphaned entry in a solution upgrade diff, explaining why the orphan cannot be safely removed.
public struct SolutionDiffReference: Codable, Sendable {
    /// ID of the referencing config (`cfg_...`).
    public var id: String
    /// Object type of the referencing config, e.g. `"Automation"` or `"Template"`.
    public var kind: String
    /// Human-readable stable identifier of the referencing config. `null` if not assigned.
    public var lookupKey: String?
    /// Explanation of how the referencing config depends on the orphaned entry.
    public var reason: String

    public init(id: String, kind: String, lookupKey: String? = nil, reason: String) {
        self.id = id
        self.kind = kind
        self.lookupKey = lookupKey
        self.reason = reason
    }

    private enum CodingKeys: String, CodingKey {
        case id
        case kind
        case lookupKey = "lookup_key"
        case reason
    }
}

/// A single config entry in a solution upgrade diff, describing what action will be taken on a specific config key.
public struct SolutionDiffEntry: Codable, Sendable {
    /// Planned action for this entry. One of `"add"` (new config), `"update"` (existing config changes), `"noop"` (no change needed), `"orphan"` (config no longer in the solution), or `"delete"` (config to be removed).
    public var action: String
    /// `true` if the config content differs between the existing and incoming solution versions.
    public var contentChanged: Bool
    /// Config ID (`cfg_...`) if this entry corresponds to an existing config record. `null` for new additions.
    public var id: String?
    /// Stable string key identifying this config entry within the solution.
    public var key: String
    /// Config object type, e.g. `"Automation"` or `"Template"`. `null` if not yet known.
    public var kind: String?
    /// Human-readable stable identifier for this config. `null` if not assigned.
    public var lookupKey: String?
    /// `true` if the MIME type of the config changed between versions.
    public var mimeTypeChanged: Bool
    /// List of other configs that reference this entry. Populated for orphaned configs that cannot be safely removed. Empty array when there are no references.
    public var referencedBy: [SolutionDiffReference]?
    /// `true` if the relative path of the config within the solution changed between versions.
    public var relativePathChanged: Bool
    /// Role of this config within the solution. Indicates whether it is a primary config or a dependency.
    public var role: String
    /// Hierarchical path of this config in the config tree. `null` if not assigned.
    public var virtualPath: String?

    public init(
        action: String,
        contentChanged: Bool,
        id: String? = nil,
        key: String,
        kind: String? = nil,
        lookupKey: String? = nil,
        mimeTypeChanged: Bool,
        referencedBy: [SolutionDiffReference]? = nil,
        relativePathChanged: Bool,
        role: String,
        virtualPath: String? = nil
    ) {
        self.action = action
        self.contentChanged = contentChanged
        self.id = id
        self.key = key
        self.kind = kind
        self.lookupKey = lookupKey
        self.mimeTypeChanged = mimeTypeChanged
        self.referencedBy = referencedBy
        self.relativePathChanged = relativePathChanged
        self.role = role
        self.virtualPath = virtualPath
    }

    private enum CodingKeys: String, CodingKey {
        case action
        case contentChanged = "content_changed"
        case id
        case key
        case kind
        case lookupKey = "lookup_key"
        case mimeTypeChanged = "mime_type_changed"
        case referencedBy = "referenced_by"
        case relativePathChanged = "relative_path_changed"
        case role
        case virtualPath = "virtual_path"
    }
}

/// Aggregate counts of each action type across all entries in a solution upgrade diff.
public struct SolutionDiffSummary: Codable, Sendable {
    /// Number of config entries that will be newly created by this upgrade.
    public var adds: Int
    /// Number of config entries that will be deleted as part of the upgrade.
    public var deletes: Int
    /// Number of config entries that are already up to date and require no changes.
    public var noops: Int
    /// Number of config entries present in the existing solution that are absent from the incoming version and have no external references blocking removal.
    public var orphans: Int
    /// Number of orphaned config entries that cannot be removed because other configs still reference them.
    public var referencedOrphans: Int
    /// Number of config entries that exist and will be updated with new content.
    public var updates: Int

    public init(
        adds: Int,
        deletes: Int,
        noops: Int,
        orphans: Int,
        referencedOrphans: Int,
        updates: Int
    ) {
        self.adds = adds
        self.deletes = deletes
        self.noops = noops
        self.orphans = orphans
        self.referencedOrphans = referencedOrphans
        self.updates = updates
    }

    private enum CodingKeys: String, CodingKey {
        case adds
        case deletes
        case noops
        case orphans
        case referencedOrphans = "referenced_orphans"
        case updates
    }
}

/// The machine-readable outcome of a Solution import attempt, indicating whether the import succeeded or requires an upgrade flow to resolve a version conflict.
public struct SolutionImportResult: Codable, Sendable {
    /// Machine-readable conflict code present when `status` is `"conflict"`, identifying the specific conflict reason. `null` when `status` is `"ready"`.
    public var code: String?
    /// Whether this result was produced by a dry-run check. `true` when the import was validated without persisting any changes.
    public var dryRun: Bool
    /// Semver string of the Solution version already present in the library. `null` when no prior version exists.
    public var existingSolutionVersion: String?
    /// Semver string of the Solution version in the bundle being imported. `null` when the bundle does not declare a version.
    public var incomingSolutionVersion: String?
    /// Human-readable description of the import status or conflict reason, suitable for display in a confirmation dialog. `null` when no detail is available.
    public var message: String?
    /// Outcome of the import check. `"ready"` means the import can proceed as a normal create or update. `"conflict"` means a version conflict was detected and the upgrade flow must be used instead.
    public var status: String
    /// Whether the caller must invoke the dedicated upgrade flow to complete the import. Mirrors `status == "conflict"` as a convenience boolean.
    public var upgradeRequired: Bool

    public init(
        code: String? = nil,
        dryRun: Bool,
        existingSolutionVersion: String? = nil,
        incomingSolutionVersion: String? = nil,
        message: String? = nil,
        status: String,
        upgradeRequired: Bool
    ) {
        self.code = code
        self.dryRun = dryRun
        self.existingSolutionVersion = existingSolutionVersion
        self.incomingSolutionVersion = incomingSolutionVersion
        self.message = message
        self.status = status
        self.upgradeRequired = upgradeRequired
    }

    private enum CodingKeys: String, CodingKey {
        case code
        case dryRun = "dry_run"
        case existingSolutionVersion = "existing_solution_version"
        case incomingSolutionVersion = "incoming_solution_version"
        case message
        case status
        case upgradeRequired = "upgrade_required"
    }
}

/// The result of importing a Solution bundle into the library, including the Solution config record, a structured import result, and the list of all configs persisted during the transaction.
