        self.installedConfigs = installedConfigs
        self.kind = kind
        self.lookupKey = lookupKey
        self.solution = solution
        self.updatedAt = updatedAt
        self.virtualPath = virtualPath
    }

    private enum CodingKeys: String, CodingKey {
